def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_aggro = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            if opp.get('budget', 0) >= 500:
                rich_aggro += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.5
    if no_water >= 2:
        danger += 1.0
    elif no_water >= 1:
        danger += 0.45

    endgame = day >= 8

    base = 16.0 + 10.0 * scarcity

    if highest_prev >= 120:
        base = min(base, 22.0 + 8.0 * scarcity)
    elif highest_prev >= 90:
        base = min(base, 26.0 + 10.0 * scarcity)
    elif highest_prev > 0:
        base = max(base, min(55.0, avg_prev * 0.55))

    if urgent_opp >= 2:
        base += 8.0
    elif urgent_opp == 1:
        base += 4.0

    if rich_aggro >= 2 and danger < 0.5:
        base -= 4.0

    if danger >= 1.5:
        bid = max(base, min(budget, highest_prev + 6.0 if highest_prev > 0 else 78.0))
    elif danger >= 0.5:
        target = highest_prev + 2.5 if 25.0 <= highest_prev <= 80.0 else 48.0 + 12.0 * scarcity
        bid = max(base, target)
    else:
        bid = base

    if endgame and hp <= 4:
        bid = max(bid, 60.0 + 10.0 * scarcity)

    max_safe = budget
    if day < 10:
        reserve_days = 10 - day
        reserve = max(0.0, reserve_days * DAILY_SALARY * 0.18)
        max_safe = max(0.0, budget - reserve)
        if danger >= 1.0:
            max_safe = budget

    if max_safe <= 0:
        max_safe = min(budget, 12.0)

    bid = min(bid, max_safe)
    bid = min(bid, budget)
    bid = max(0.0, bid)

    if budget < 25:
        bid = min(bid, budget)
    elif danger < 0.5 and highest_prev >= 100:
        bid = min(bid, 24.0 + 6.0 * scarcity)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 1)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for k, v in opponents_status.items():
        if v is not None and v.get('alive', False):
            alive_opps.append((k, v))

    if not alive_opps:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Immediate reaction to yesterday's bids
    yesterday_bids = []
    yesterday_hp_after = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass
        if isinstance(prev, dict) and prev.get('hp_after') is not None:
            try:
                yesterday_hp_after.append(int(prev['hp_after']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = (sum(yesterday_bids) / len(yesterday_bids)) if yesterday_bids else 0.0

    # Estimate how many water units are likely available; use as a pressure proxy
    # (We cannot see opponents' current bids, so we bias toward securing at least one unit.)
    expected_units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 1
    if expected_units < 1:
        expected_units = 1

    # Baseline bid: moderate, tuned by our hp and no-water streak
    # If our hp is low or we already missed water, bid higher.
    if my_hp <= 2 or my_no_water_days >= 2:
        base = DAILY_SALARY * 0.85
    elif my_hp <= 4 or my_no_water_days == 1:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.5

    # If yesterday's max bid was very high, others likely compete strongly today too.
    # Raise bid to be competitive but avoid overspending.
    if highest_prev_bid >= DAILY_SALARY * 1.2:
        base = max(base, DAILY_SALARY * 0.75)
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        base = max(base, DAILY_SALARY * 0.6)

    # If average yesterday bid was high, slightly increase.
    if avg_prev_bid >= DAILY_SALARY * 0.95:
        base = max(base, DAILY_SALARY * 0.62)

    # Budget guardrails: never exceed budget.
    # Also, if supply is low (near MIN_SUPPLY), competition is higher; slightly increase.
    if supply <= float(MIN_SUPPLY) + 0.5:
        base *= 1.06

    # Convert to final bid with a small day-based wobble to avoid ties.
    wobble = 1.0 + (0.01 * ((int(day) % 5) - 2))
    bid = base * wobble

    # Ensure bid is within reasonable bounds relative to budget.
    if my_budget <= 0:
        return 0.0

    bid = float(min(my_budget, bid))

    # If budget is too low, still try to bid something proportional to survival need.
    if bid < 1e-6:
        if my_hp <= 2:
            return float(min(my_budget, DAILY_SALARY * 0.9))
        return float(min(my_budget, DAILY_SALARY * 0.4))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.75

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8: # High pressure from opponents
            if my_status['hp'] > 4: # Relatively healthy, can risk saving a bit
                bid_amount = DAILY_SALARY * 0.65
            else: # HP is critical, must bid high to survive
                bid_amount = DAILY_SALARY * 0.95
        else: # Moderate pressure
            if my_status['hp'] <= 3: # HP is getting low, be more aggressive
                bid_amount = max(DAILY_SALARY * 0.85, highest_prev_bid + 10)
            else: # Healthy enough, try to be competitive but not overspend
                bid_amount = max(DAILY_SALARY * 0.65, highest_prev_bid + 5)
    else:
        # Day 1 or no previous bids available
        if my_status['hp'] <= 2: 
            bid_amount = DAILY_SALARY * 0.9
        else:
            bid_amount = base_bid

    remaining_days = EPISODE_DAYS - day_context['day']

    # Aggressive push in the final days if budget allows
    if remaining_days <= 2 and my_status['budget'] > DAILY_SALARY * 1.5:
        bid_amount = max(bid_amount, DAILY_SALARY * 0.98)
    # Desperate bid if low on budget and HP in final days
    elif remaining_days <= 2 and my_status['budget'] < DAILY_SALARY * 0.5 and my_status['hp'] <= 2:
        bid_amount = my_status['budget'] # Bid everything
    # Conserve early if healthy
    elif day_context['day'] <= 3 and my_status['hp'] > 6:
        bid_amount = min(bid_amount, DAILY_SALARY * 0.7)

    final_bid = min(my_status['budget'], bid_amount)

    return max(0.01, final_bid)

